import React, { useState, useEffect } from "react";
import axios from "axios";

const Orders = () => {
  const [allOrders, setAllOrders] = useState([]);

  useEffect(() => {
    axios.get("http://localhost:8080/allOrders").then((res) => {
      setAllOrders(res.data);
    });
  }, []);

  const handleDelete = async (id) => {
    if (window.confirm("Kya aap is order ko delete karna chahte hain?")) {
      try {
        await axios.delete(`http://localhost:8080/deleteOrder/${id}`);
        setAllOrders(allOrders.filter((order) => order._id !== id));
        alert("Order deleted!");
      } catch (err) {
        alert("Delete karne mein error aaya!");
      }
    }
  };

  const handleUpdate = async (id, currentQty, currentPrice) => {
    const newQty = prompt("Nayi Quantity daalein:", currentQty);
    const newPrice = prompt("Naya Price daalein:", currentPrice);

    if (newQty && newPrice) {
      try {
        await axios.put(`http://localhost:8080/updateOrder/${id}`, {
          qty: Number(newQty),
          price: Number(newPrice),
        });
        window.location.reload();
      } catch (err) {
        alert("Update fail ho gaya!");
      }
    }
  };

  return (
    <div className="orders">
      {allOrders.length === 0 ? (
        <p>No orders placed yet.</p>
      ) : (
        <div className="order-table">
          <table>
            <thead>
              <tr>
                <th>Instrument</th>
                <th>Qty.</th>
                <th>Price</th>
                <th>Status</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {allOrders.map((order) => {
                const isBuy = order.mode === "BUY";
                return (
                  <tr key={order._id}>
                    <td>{order.name}</td>
                    <td>{order.qty}</td>
                    <td>{order.price.toFixed(2)}</td>
                    <td style={{ color: isBuy ? "#4184f3" : "#ff5722", fontWeight: "bold" }}>
                      {order.mode}
                    </td>
                    <td>
                      <button 
                        onClick={() => handleUpdate(order._id, order.qty, order.price)}
                        style={{ marginRight: "10px", cursor: "pointer", padding: "2px 8px" }}
                      >
                        Edit
                      </button>
                      <button 
                        onClick={() => handleDelete(order._id)}
                        style={{ color: "red", cursor: "pointer", padding: "2px 8px" }}
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default Orders;
